import React from 'react';
import { useApp } from '../context/AppContext';
import { useParams, useNavigate } from 'react-router-dom';
import { Pencil } from 'lucide-react';
import { T } from '../edit/T';
import { useEdit } from '../edit/EditContext';

export default function ProductCard({ product, size = 'normal' }) {
 const { navigate, t, graphics } = useApp();
 const ed = useEdit();
 const rnav = useNavigate();
 const sheet = graphics.some(g => g.id === product.id && g.name === product.name) ? 'graphics' : 'products';
 const params = useParams();
 const subCat = params?.subCat;
 const isSmall = size === 'small';
 const price = Number(product.price) > 0 ? `₪${Number(product.price)}` : product.priceNote || t('product.price_note_short');
 const isPriceFixed = Number(product.price) > 0;

 return (
 <div onClick={() => navigate('product', { ...product, _fromSubCategory: subCat || product.category })}
 style={{
 background: 'var(--warm-white)',
 border: '1px solid var(--border-light)',
 borderRadius: isSmall ? '16px' : '20px',
 overflow: 'hidden', cursor: 'pointer',
 transition: 'transform 0.25s cubic-bezier(0.22,1,0.36,1), box-shadow 0.25s ease',
 }}
 onMouseEnter={e => { e.currentTarget.style.transform = 'translateY(-5px)'; e.currentTarget.style.boxShadow = 'var(--shadow-lg)'; }}
 onMouseLeave={e => { e.currentTarget.style.transform = 'translateY(0)'; e.currentTarget.style.boxShadow = 'none'; }}
 >
 {/* תמונה */}
 <div style={{
 background: 'linear-gradient(145deg, var(--cream), var(--rose-soft))',
 paddingTop: isSmall ? '90%' : '105%',
 position: 'relative', overflow: 'hidden',
 }}>
 {product.images?.[0] ? (
 <img src={product.images[0]} alt={product.name}
 style={{ position: 'absolute', inset: 0, width: '100%', height: '100%', objectFit: 'cover' }} />
 ) : (
 <div style={{ position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: isSmall ? '34px' : '46px', animation: 'float 3s ease-in-out infinite' }}>
 {product.emoji || ''}
 </div>
 )}
 {ed?.editMode && (
 <div className="card-tools">
 <button className="lbl" onClickCapture={e => { e.preventDefault(); e.stopPropagation(); rnav(`/admin/catalog?tab=${sheet}&edit=${encodeURIComponent(product.id)}`); }}><Pencil size={13} /> עריכת מוצר</button>
 </div>
 )}
 {/* תגית מבצע */}
 {product.dealQty && product.dealPrice && (
 <div style={{
 position: 'absolute', top: '9px', right: '9px',
 background: 'var(--grad-amber)', color: 'white',
 padding: '4px 10px', borderRadius: '20px',
 fontSize: '11px', fontWeight: '800',
 boxShadow: '0 2px 8px rgba(196,134,26,0.35)',
 }}><T k="product.deal_badge" /> {product.dealLabel || ''}</div>
 )}
 {/* תג מחיר */}
 <div style={{
 position: 'absolute', bottom: '9px', left: '9px',
 background: isPriceFixed ? 'var(--amber)' : 'rgba(139,90,107,0.82)',
 backdropFilter: 'blur(6px)',
 color: 'white', padding: '5px 12px', borderRadius: '50px',
 fontSize: '13px', fontWeight: '800',
 }}>
 {price}
 </div>
 </div>

 {/* מידע */}
 <div style={{ padding: isSmall ? '11px 13px' : '14px 16px' }}>
 <h3 style={{ fontFamily: 'var(--font-display)', fontSize: isSmall ? '15px' : '19px', fontWeight: '700', color: 'var(--rose)', marginBottom: '3px', lineHeight: '1.3' }}>
 {product.name}
 </h3>
 {!isSmall && (
 <p style={{ fontSize: '12px', color: 'var(--light)', lineHeight: '1.55', display: '-webkit-box', WebkitLineClamp: 2, WebkitBoxOrient: 'vertical', overflow: 'hidden' }}>
 {product.description}
 </p>
 )}
 </div>
 </div>
 );
}
